CREATE TABLE IF NOT EXISTS "article_translations" ("id" serial PRIMARY KEY NOT NULL,"article_id" integer NOT NULL,"locale" text NOT NULL,"title" text DEFAULT '' NOT NULL,"slug" text DEFAULT '' NOT NULL,"excerpt" text DEFAULT '' NOT NULL,"hero_alt" text DEFAULT '' NOT NULL,"body" jsonb DEFAULT '[]'::jsonb NOT NULL,"seo_title" text,"seo_description" text,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL);
DO $$ BEGIN ALTER TABLE "article_translations" ADD CONSTRAINT "article_translations_article_id_articles_id_fk" FOREIGN KEY ("article_id") REFERENCES "articles"("id") ON DELETE cascade ON UPDATE no action; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE UNIQUE INDEX IF NOT EXISTS "article_translations_article_locale_unique" ON "article_translations" USING btree ("article_id","locale");
CREATE UNIQUE INDEX IF NOT EXISTS "article_translations_locale_slug_unique" ON "article_translations" USING btree ("locale","slug");
INSERT INTO "article_translations" ("article_id","locale","title","slug","excerpt","hero_alt","body","seo_title","seo_description","created_at","updated_at") SELECT "id",'id',"title","slug","excerpt","hero_image_alt","body","seo_title","seo_description","created_at","updated_at" FROM "articles" ON CONFLICT ("article_id","locale") DO NOTHING;
